input.command:
cat > /tmp/kcr-test/t.js <<'EOF'
const puppeteer = require('puppeteer-core');
const F = 'file://' + process.argv[2];
(async () => {
  const b = await puppeteer.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: 'new' });
  const p = await b.newPage();
  const errs = [];
  p.on('pageerror', e => errs.push('pageerror ' + e.message));
  p.on('console', m => { if (m.type() === 'error') errs.push('console ' + m.text()); });
  await p.setViewport({ width: 1440, height: 1000 });
  await p.goto(F, { waitUntil: 'networkidle0' });
  const r = {};
  // hover chart column 11
  const box = await (await p.$('.col[data-i="11"] .band')).boundingBox();
  await p.mouse.move(box.x + box.width / 2, box.y + box.height - 20);
  r.tooltip = await p.$eval('.tooltip', t => t.hidden ? 'HIDDEN' : t.innerText.replace(/\n/g, ' | '));
  // switch to online
  await p.click('input[value="online"]');
  await p.mouse.move(box.x + box.width / 2, box.y + box.height - 20);
  r.tooltipOnline = await p.$eval('.tooltip', t => t.hidden ? 'HIDDEN' : t.innerText.replace(/\n/g, ' | '));
  r.yTicks = await p.$$eval('.chart svg > text', ts => ts.map(t => t.textContent).join(','));
  r.insight = await p.$eval('#chartInsight', e => e.textContent);
  // keyboard focus
  await p.mouse.move(0, 0);
  await p.focus('.col[data-i="11"]'); await p.keyboard.press('ArrowLeft');
  r.kbd = await p.evaluate(() => document.activeElement.getAttribute('aria-label') + ' / tt: ' + document.querySelector('.tooltip').innerText.replace(/\n/g,' | '));
  // sort cafes
  const names = () => p.$$eval('#cafeBody tr[data-row] th', ths => ths.map(t => t.dataset.value).join(', '));
  await p.click('#cafeTable thead th:nth-child(5) button'); r.sortChange = await names() + ' ' + await p.$eval('#cafeTable thead th:nth-child(5)', t => t.getAttribute('aria-sort'));
  await p.click('#cafeTable thead th:nth-child(5) button'); r.sortChange2 = await names();
  await p.click('#cafeTable thead th:nth-child(1) button'); r.sortName = await names();
  await p.click('#cafeTable thead th:nth-child(4) button'); r.sortTicket = await names();
  // search
  await p.type('#search', 'tomas');
  r.search = await p.$eval('#filterText', e => e.textContent);
  r.visibleOrders = await p.$$eval('#ordersBody tr[data-row]:not([hidden]) .c-cust', e => e.map(x => x.textContent).join());
  await p.keyboard.press('Escape');
  r.afterEsc = await p.$$eval('#ordersBody tr[data-row]:not([hidden])', e => e.length);
  // mobile drawer
  await p.setViewport({ width: 390, height: 844 });
  await new Promise(r => setTimeout(r, 300));
  r.scrollW = await p.evaluate(() => document.documentElement.scrollWidth);
  await p.click('#navOpen'); await new Promise(r => setTimeout(r, 300));
  r.drawer = await p.evaluate(() => ({ open: document.getElementById('sidebar').classList.contains('is-open'), focus: document.activeElement.textContent.trim(), inert: document.getElementById('mainCol').inert, vis: getComputedStyle(document.getElementById('sidebar')).visibility }));
  await p.keyboard.press('Escape');
  r.drawerClosed = await p.evaluate(() => ({ open: document.getElementById('sidebar').classList.contains('is-open'), focus: document.activeElement.id }));
  // touch tap
  r.errors = errs;
  console.log(JSON.stringify(r, null, 1));
  await b.close();
})();
EOF
cd /tmp/kcr-test && node t.js "$RUN/work/index.html"

